"use strict";
// Runs in a Node island. `ttl` is absent for a session opened without one
// and `started` answers a Date the island made: both contradict what the
// declarations let compiled code assume.
exports.open = function (name, ttl) {
  return ttl === undefined ? { id: name } : { id: name, ttl };
};
exports.label = function (session) {
  return "session " + session.id;
};
exports.each = function (items, visit) {
  for (let i = 0; i < items.length; i++) visit(items[i], i);
};
exports.started = function () {
  return new Date(0);
};
exports.load = function (path) {
  return { name: path, retries: "many" };
};
exports.quota = function () {
  return {};
};
exports.sizes = function () {
  return ["wide"];
};
